values
  ('MG', 'MG-P-20', 'Achat, taux normal 20 %, TVA déductible', '{}'::jsonb, 'Achat local de biens ou de services dont la taxe est déduite', 'percent', 20, 'purchase', 'domestic', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.17 A 1° — la taxe qui figure distinctement sur les factures d''achats de produits non exonérés ou de services nécessaires à l''exploitation normale, payés par voie bancaire ou par monnaie mobile, est déductible, la facture étant conforme à l''art. IV-21 du Code des procédures fiscales ; art. 06.01.21 — la taxe n''est déductible que lorsque l''exigibilité intervient chez le fournisseur. Déduction entière : le pack ne calcule ni le prorata de l''art. 06.01.17 A 2° ni le paiement par voie bancaire.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-P-20-ND', 'Achat, taux 20 %, TVA non déductible', '{}'::jsonb, 'Achat dont la taxe est exclue de la déduction par l''art. 06.01.18', 'percent', 20, 'purchase', 'domestic', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.18 — n''est pas déductible la taxe sur les immeubles autres qu''industriels, artisanaux, commerciaux, hôteliers, de restauration, agricoles ou miniers, sur les voitures particulières, les meubles meublants (sauf hôtellerie et restauration), l''énergie non liée à l''exploitation, les denrées alimentaires consommées dans l''entreprise, l''essence tourisme, le super carburant, le gasoil et le fuel-oil (sauf les usages de l''art. 06.01.17 B). La taxe suit la charge au compte 6318 et n''atteint aucune case.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-P-5', 'Achat de gaz butane, taux réduit 5 %', '{}'::jsonb, 'Achat local de gaz butane et de son contenant, taxe déduite', 'percent', 5, 'purchase', 'domestic', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.12 — taux réduit de 5 % sur les ventes de gaz butane et de leur contenant ; art. 06.01.17 A 1° — déduction de la taxe qui figure sur la facture d''achat.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-P-EX', 'Achat exonéré', '{}'::jsonb, 'Achat d''un bien ou d''un service exonéré, sans taxe', 'percent', 0, 'purchase', 'exempt', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.06 — opérations qui ne donnent pas lieu à l''application de la taxe ; aucune taxe n''est déductible sur ce qu''elles ne portent pas.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-P-IMP', 'Importation de biens, TVA payée à la Douane', '{}'::jsonb, 'Taxe due sur une importation, liquidée par les Douanes et déduite', 'percent', 20, 'purchase', 'import', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.03 1° — sont soumises à la taxe les importations, quelle que soit la qualité de l''importateur ; art. 06.01.14 — la taxe due au titre des importations est liquidée et perçue par le service des Douanes ; art. 06.01.17 A 2° — la taxe acquittée à l''importation est déductible. Comptabilisée au compte 4458 contre la déduction, jusqu''au règlement de la Douane. Le taux réduit de 5 % du gaz butane à l''importation n''a pas de code.', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-P-RC', 'Service d''un prestataire non établi, TVA due par le bénéficiaire', '{}'::jsonb, 'Prestation taxable faite à Madagascar par une personne sans établissement, dont le bénéficiaire verse la taxe', 'percent', 20, 'purchase', 'foreign_services_received', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.09 bis — la personne sans établissement à Madagascar qui y effectue des prestations taxables doit y faire accréditer un représentant ; à défaut, la taxe est liquidée et reversée par le bénéficiaire auprès du Receveur des impôts au plus tard le 15 du mois suivant, sur un imprimé distinct de la déclaration de TVA ; la déduction par le bénéficiaire assujetti suit la règle générale et n''est possible que lorsque l''exigibilité intervient chez le prestataire étranger. Le pack porte les deux montants dans les cases RC et RCD de la déclaration ; l''imprimé distinct du texte n''a pas été lu.', null, null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-S-20', 'Vente, taux normal 20 %', '{}'::jsonb, 'Livraison de biens ou prestation de services faite à Madagascar', 'percent', 20, 'sale', 'domestic', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.02 — les affaires réalisées à Madagascar par les personnes qui achètent pour revendre ou accomplissent des actes d''une activité commerciale, industrielle, agricole, artisanale, minière, hôtelière, de prestation de services ou de profession libérale sont soumises à la taxe ; art. 06.01.12 — le taux normal est de 20 p. 100.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-S-5', 'Vente de gaz butane, taux réduit 5 %', '{}'::jsonb, 'Vente de gaz butane (tarif douanier 2711.13 00) et de son contenant (7311.00 00)', 'percent', 5, 'sale', 'domestic', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.12 — les importations et les ventes de gaz butane et de leur contenant, relevant des tarifs douaniers 2711.13 00 et 7311.00 00, sont taxées au taux réduit de 5 %.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-S-EX', 'Vente exonérée', '{}'::jsonb, 'Opération que l''art. 06.01.06 ne soumet pas à la taxe : écolages, intérêts bancaires, assurances vie…', 'percent', 0, 'sale', 'exempt', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.06 — ne donnent pas lieu à l''application de la taxe les écolages payés en rémunération des cours d''enseignement, les intérêts versés par le Trésor, les opérations sur titres, les intérêts bancaires, les contrats d''assurance vie, etc. (liste de l''article, reprise en partie) ; art. 06.01.05 — qui exerce des opérations exonérées et taxables n''est assujetti que sur les taxables, et la déduction suit l''art. 06.01.17. L''article contient d''autres exonérations que le pack ne liste pas.', 'E', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null),
  ('MG', 'MG-S-EXP', 'Vente à l''exportation, taux zéro', '{}'::jsonb, 'Exportation de biens ou de services, taxée au taux de 0 %', 'percent', 0, 'sale', 'export', date '2024-01-01', null, 'Code des impôts selon la loi de finances 2024, art. 06.01.12 — les exportations de biens et de services sont taxées au taux de 0 p. 100 ; l''opération reste imposable, et le crédit de taxe qui en résulte ouvre droit au remboursement de l''art. 06.01.24 (qui exige les formalités d''exportation et le rapatriement des devises).', 'G', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'code-impots', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

