insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MG', 'MG-TVA-MENSUELLE', 'Déclaration mensuelle de la taxe sur la valeur ajoutée', array['month']::declaration_period[], 'month'::declaration_period, date '2024-01-01', null, 'Code des impôts, art. 06.01.16 — la taxe est calculée par le redevable à la fin de chaque période mensuelle à raison des opérations de cette période, compte tenu des déductions des articles 06.01.17 et suivants ; elle est versée au plus tard le 15 du mois suivant à l''aide de la déclaration établie sur un imprimé fourni par l''Administration, et la déclaration doit être faite dans le même délai même si le redevable n''a pas de versement à effectuer ; art. 06.01.23 — le crédit de taxe est reporté sur les échéances mensuelles suivantes. L''imprimé n''a pas pu être lu : les lignes sont celles du pack, groupées sous les montants que le texte nomme, et l''écart est écrit dans le README.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Code des impôts, art. 06.01.16 — versée au plus tard le 15 du mois suivant la période, et déclaration dans le même délai même sans versement. Les règles de report d''un jour non ouvré du Code des procédures fiscales n''ont pas été lues.', 'code-impots', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
