values
  ('MG', 'MG-TVA-MENSUELLE', 'EXP', 'base', 'Exportations de biens et de services (taux 0 %)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.12 — exportations taxées à 0 p. 100. Ligne propre au pack : l''imprimé fourni par l''Administration (art. 06.01.16) n''a pas pu être lu.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'EXO', 'base', 'Opérations exonérées', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.06. Ligne propre au pack : l''imprimé fourni par l''Administration (art. 06.01.16) n''a pas pu être lu.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'S20', 'base', 'Ventes et prestations au taux de 20 % — base', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.12 — taux normal. Ligne propre au pack : l''imprimé fourni par l''Administration (art. 06.01.16) n''a pas pu être lu.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'S20', 'tax', 'TVA collectée au taux de 20 %', '{}'::jsonb, 35, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.12 et 06.01.16 — la taxe est calculée par le redevable à la fin de chaque période mensuelle, nette des avoirs émis.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'S5', 'base', 'Ventes de gaz butane au taux de 5 % — base', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.12 — taux réduit. Ligne propre au pack : l''imprimé fourni par l''Administration (art. 06.01.16) n''a pas pu être lu.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'S5', 'tax', 'TVA collectée au taux de 5 %', '{}'::jsonb, 45, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.12 et 06.01.16.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'RC', 'base', 'Prestations de non-établis, taxe due par le bénéficiaire — base', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.09 bis. Ligne propre au pack : l''imprimé fourni par l''Administration (art. 06.01.16) n''a pas pu être lu.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'RC', 'tax', 'TVA due sur les prestations de non-établis', '{}'::jsonb, 55, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.09 bis — taxe liquidée et reversée par le bénéficiaire.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'T1', 'total', 'Total de la TVA collectée ou due', '{}'::jsonb, 60, null, array['S20:tax', 'S5:tax', 'RC:tax']::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.16 — somme de la taxe collectée aux deux taux et de la taxe due sur les prestations de non-établis.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'P20', 'base', 'Achats locaux au taux de 20 % — base', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.17 A 1°. Ligne propre au pack : l''imprimé fourni par l''Administration (art. 06.01.16) n''a pas pu être lu.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'P20', 'tax', 'TVA déductible sur achats locaux au taux de 20 %', '{}'::jsonb, 75, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.17 A 1° — nette des avoirs reçus.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'P5', 'base', 'Achats de gaz butane au taux de 5 % — base', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.12 et 06.01.17 A 1°. Ligne propre au pack : l''imprimé fourni par l''Administration (art. 06.01.16) n''a pas pu être lu.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'P5', 'tax', 'TVA déductible sur achats de gaz butane', '{}'::jsonb, 85, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.17 A 1°.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'IMP', 'base', 'Importations — base', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.17 A 2°. Ligne propre au pack : l''imprimé fourni par l''Administration (art. 06.01.16) n''a pas pu être lu.', 'code-impots'),
  ('MG', 'MG-TVA-MENSUELLE', 'IMP', 'tax', 'TVA déductible acquittée à l''importation', '{}'::jsonb, 95, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code des impôts, art. 06.01.17 A 2° — la taxe acquittée à l''importation au cours de la même période.', 'code-impots'),
